// Turn the drafted WhatsApp messages into a single review list.
const raw = $input.first().json.stdout || '[]';
let drafts = [];
try { drafts = JSON.parse(raw); } catch (e) { drafts = []; }

if (!drafts.length) return [{ json: { text: 'No WhatsApp drafts today.' } }];

const lines = drafts
  .sort((a, b) => (b.score || 0) - (a.score || 0))
  .slice(0, 25)
  .map((d, i) => `${i + 1}. *${d.name}* — ${d.offer} (${d.score})\n${d.wa_link}`);

return [{ json: {
  count: drafts.length,
  text: `*${drafts.length} WhatsApp drafts ready*\n\nTap a link, check the message, send it.\n\n` + lines.join('\n\n')
} }];
